{"new_string":"def transpose(text):
    """Transpose lines, padding gaps but preserving only real trailing spaces."""
    rows = text.split("\n")
    result = []

    for column_index in range(max(map(len, rows))):
        column = []
        last_present = 0
        for row in rows:
            if column_index < len(row):
                column.append(row[column_index])
                last_present = len(column)
            else:
                column.append(" ")
        result.append("".join(column[:last_present]))

    return "\n".join(result)
